<?php
namespace App\Livewire;
use App\Models\ExamPaper;use App\Models\Student;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class MarksEntry extends Component {public string $paperId='';public array $scores=[];protected function canManage():bool{return in_array(Auth::user()->role,['admin','academic_admin'],true);}protected function canEnter(ExamPaper $paper):bool{$user=Auth::user();if($this->canManage())return true;return $user->role==='teacher'&&DB::table('staff_subjects')->where(['school_id'=>$paper->exam->school_id,'term_id'=>$paper->exam->term_id,'user_id'=>$user->id,'subject_id'=>$paper->subject_id,'school_class_id'=>$paper->exam->school_class_id])->exists();}public function save(string $status='draft'):void{$paper=ExamPaper::with('exam')->findOrFail($this->paperId);if(!$paper->exam->term->isOpen()||!$this->canEnter($paper)){abort(403);}if(DB::table('exam_paper_submissions')->where('exam_paper_id',$paper->id)->value('status')==='approved'){session()->flash('error','Approved marks must be reopened first.');return;}$students=Student::where('school_id',$paper->exam->school_id)->where('school_class_id',$paper->exam->school_class_id)->where('status','active')->get();foreach($students as $student){$score=$this->scores[$student->id]??null;if($score!==null&&($score<0||$score>$paper->maximum_score)){$this->addError('scores.'.$student->id,'Score must be between 0 and '.$paper->maximum_score);return;}}DB::transaction(function()use($paper,$students,$status){foreach($students as $student)DB::table('exam_marks')->updateOrInsert(['exam_paper_id'=>$paper->id,'student_id'=>$student->id],['score'=>$this->scores[$student->id]??null,'entered_by'=>Auth::id(),'updated_at'=>now(),'created_at'=>now()]);DB::table('exam_paper_submissions')->updateOrInsert(['exam_paper_id'=>$paper->id],['status'=>$status,'submitted_by'=>$status==='submitted'?Auth::id():null,'submitted_at'=>$status==='submitted'?now():null,'updated_at'=>now(),'created_at'=>now()]);});session()->flash('status',$status==='submitted'?'Marks submitted for approval.':'Marks saved as draft.');}public function approve():void{$paper=ExamPaper::with('exam.term')->findOrFail($this->paperId);if(!$this->canManage()||!$paper->exam->term->isOpen())abort(403);DB::table('exam_paper_submissions')->updateOrInsert(['exam_paper_id'=>$paper->id],['status'=>'approved','approved_by'=>Auth::id(),'approved_at'=>now(),'updated_at'=>now(),'created_at'=>now()]);session()->flash('status','Paper approved.');}public function reopen():void{$paper=ExamPaper::with('exam.term')->findOrFail($this->paperId);if(!$this->canManage()||!$paper->exam->term->isOpen())abort(403);DB::table('exam_paper_submissions')->where('exam_paper_id',$paper->id)->update(['status'=>'draft','approved_by'=>null,'approved_at'=>null,'updated_at'=>now()]);session()->flash('status','Paper reopened.');}public function render(){$school=Auth::user()->school;$term=$school->currentTerm();$papers=ExamPaper::with(['exam.schoolClass','exam.term','subject'])->whereHas('exam',fn($q)=>$q->where('school_id',$school->id)->when($term,fn($q)=>$q->where('term_id',$term->id)))->get()->filter(fn($p)=>$this->canEnter($p));$paper=$this->paperId?ExamPaper::with(['exam.term'])->find($this->paperId):null;$students=$paper?Student::where('school_id',$school->id)->where('school_class_id',$paper->exam->school_class_id)->where('status','active')->orderBy('name')->get():collect();if($paper&&!$this->scores)$this->scores=DB::table('exam_marks')->where('exam_paper_id',$paper->id)->pluck('score','student_id')->all();$status=$paper?DB::table('exam_paper_submissions')->where('exam_paper_id',$paper->id)->value('status')??'draft':null;return view('livewire.marks-entry',['papers'=>$papers,'paper'=>$paper,'students'=>$students,'paperStatus'=>$status,'canManage'=>$this->canManage(),'pageTitle'=>'Enter Marks']);}}
